 public class Main {

    public static void main(String[] args) throws Exception {
        Solver<Object> solver = Solver.getInstance("C-small-attempt1.in");
        Scanner sc = solver.getScanner();
        int casenum = sc.nextInt();
        for(int caseid=0;caseid<casenum;caseid++) {
            int h = sc.nextInt();
            int w = sc.nextInt();
            char[][] map = new char[h][];
            for(int i=0;i<h;i++) {
                map[i] = sc.next().toCharArray();
            }
            solver.addTask(new Task(h,w,map));
        }
        solver.finish();
    }

 }
 class Task implements Callable<Object> {
    public static final String IMPOSSIBLE = "IMPOSSIBLE\n";
    int h,w;
    char[][] map;

    public Task(int h, int w, char[][] map) {
        super();
        this.h = h;
        this.w = w;
        this.map = map;
    }

    int[][] shooterH;
    int[][] shooterV;
    @Override
    public Object call() throws Exception {
        shooterH = new int[h][w];
        shooterV = new int[h][w];
        for(int i=0;i<h;i++) {
            Arrays.fill(shooterH[i], -1);
            Arrays.fill(shooterV[i], -1);
        }
        boolean[] canHorizontial = new boolean[110];
        boolean[] canVertical = new boolean[110];
        int[] shooterI = new int[110];
        int[] shooterJ = new int[110];
        int shooterNum = 0;
        for(int i=0;i<h;i++) {
            for(int j=0;j<w;j++) {
                if (map[i][j] == '-' || map[i][j] == '|') {
                    shooterI[shooterNum] = i;
                    shooterJ[shooterNum] = j;
                    if (beam(map,i,j,0,shooterNum)) {
                        canHorizontial[shooterNum] = true;
                    }
                    if (beam(map,i,j,1,shooterNum)) {
                        canVertical[shooterNum] = true;
                    }
                    if (!canHorizontial[shooterNum] && !canVertical[shooterNum]) {
                        return IMPOSSIBLE;
                    }
                    shooterNum++;
                }
            }
        }
        TwoSAT sat = new TwoSAT(shooterNum);

        for(int i=0;i<shooterNum;i++) {
            if (!canHorizontial[i]) {
                sat.addClause(false, i, false, i);
            }
            if (!canVertical[i]) {
                sat.addClause(true, i, true, i);
            }
        }
        for(int i=0;i<h;i++) {
            for(int j=0;j<w;j++) {
                if (map[i][j] != '.') {
                    continue;
                }
                if (shooterH[i][j] == -1 && shooterV[i][j] == -1) {
                    return IMPOSSIBLE;
                }
                if (shooterH[i][j] == -1) {
                    sat.addClause(false, shooterV[i][j], false, shooterV[i][j]);
                }else if(shooterV[i][j] == -1) {
                    sat.addClause(true, shooterH[i][j], true, shooterH[i][j]);
                }else{
                    sat.addClause(true, shooterH[i][j], false, shooterV[i][j]);
                }
            }
        }
        boolean[] ans = sat.solve();
        if (ans == null) {
            return IMPOSSIBLE;
        }
        for(int i=0;i<shooterNum;i++) {
            map[shooterI[i]][shooterJ[i]] = ans[i] ? '-' : '|';
        }
        StringBuilder sb = new StringBuilder();
        sb.append("POSSIBLE\n");
        for(int i=0;i<h;i++) {  
            for(int j=0;j<w;j++) {
                sb.append(map[i][j]);
            }
            sb.append('\n');
        }
        return sb.toString();
    }

    public static final int[] DI = {0,-1,0,1};
    public static final int[] DJ = {1,0,-1,0};
    public boolean beam(char[][] map,int si,int sj,int hv,int beamId) {
        if (beam(map,si,sj,0+hv,beamId,false) && beam(map,si,sj,2+hv,beamId,false)) {
            beam(map,si,sj,0+hv,beamId,true);
            beam(map,si,sj,2+hv,beamId,true);
            return true;
        }
        return false;
    }
    public boolean beam(char[][] map,int si,int sj,int dir,int beamId,boolean write) {
        int ci = si;
        int cj = sj;
        while(true) {
            ci += DI[dir];
            cj += DJ[dir];

            if (ci < 0 || ci >= h || cj < 0 || cj >= w || map[ci][cj] == '#') {
                return true;
            }

            if (map[ci][cj] == '-' || map[ci][cj] == '|') {
                return false;
            }

            if (map[ci][cj] == '/') {
                dir ^= 1;
            }else if(map[ci][cj] == '\\') {
                dir ^= 3;
            }

            if (map[ci][cj] == '.' && write) {
                if (dir == 0 || dir == 2) {
                    shooterH[ci][cj] = beamId;
                }else{
                    shooterV[ci][cj] = beamId;
                }
            }
        }
    }

 }
 class TwoSAT {
    int n;
    SCC graph;
    public TwoSAT(int n) {
        this.n = n;
        graph = new SCC(n * 2); 
    }


    public void addClause(boolean tf1, int x1, boolean tf2, int x2) {

        graph.addEdge(x1 + (tf1 ? 0 : n), x2 + (tf2 ? n : 0)); 
        graph.addEdge(x2 + (tf2 ? 0 : n), x1 + (tf1 ? n : 0)); 
    }


    public boolean[] solve() {
        graph.scc();
        int[] order = graph.order;
        boolean[] res = new boolean[n];
        for(int i=0;i<n;i++) {
            if (order[i] == order[i+n]) {
                return null;
            }
            if (order[i+n] > order[i]) {
                res[i] = true;
            }
        }
        return res;
    }
 }
 class SCC {
    int n;
    ArrayList<Integer>[] graph; 
    ArrayList<Integer>[] rgraph; 
    ArrayList<Integer> vertices; 
    boolean[] used;
    int[] order; 
    int sccNum;

    @SuppressWarnings("unchecked")
    public SCC(int n) {
        this.n = n;
        graph = new ArrayList[n];
        rgraph = new ArrayList[n];
        for(int i=0;i<n;i++) {
            graph[i] = new ArrayList<>();
            rgraph[i] = new ArrayList<>();
        }
    }

    public void addEdge(int from,int to) {

        graph[from].add(to);
        rgraph[to].add(from);
    }

    private void dfs(int v) {
        used[v] = true;
        for(int u: graph[v]) {
            if (!used[u]) {
                dfs(u);
            }
        }
        vertices.add(v);
    }

    private void rdfs(int v, int k) {
        used[v] = true;
        order[v] = k;
        for(int u: rgraph[v]) {
            if (!used[u]) {
                rdfs(u, k);
            }
        }
    }

    public void scc() {
        used = new boolean[n];
        order = new int[n];
        vertices = new ArrayList<>();
        sccNum = 0;
        for(int i=0;i<n;i++) {
            if (!used[i]) {
                dfs(i);
            }
        }
        Arrays.fill(used, false);
        for(int i=vertices.size()-1;i>=0;i--) {
            int v = vertices.get(i);
            if (!used[v]) {
                rdfs(v, sccNum++);
            }
        }
    }


    @SuppressWarnings("unchecked")
    public ArrayList<Integer>[] restoreSCCs() {
        ArrayList<Integer>[] res = new ArrayList[sccNum];
        for(int i=0;i<sccNum;i++) {
            res[i] = new ArrayList<>();
        }
        for(int i=0;i<n;i++) {
            res[order[i]].add(i);
        }
        return res;
    }
 }

