package a;















 public class Main {

    public static void main(String[] args) throws Exception {
        Solver<Object> solver = Solver.getInstance("A-small-attempt1.in");
        Scanner sc = solver.getScanner();
        int casenum = sc.nextInt();
        for(int caseid=0;caseid<casenum;caseid++) {
            int n = sc.nextInt();
            int p = sc.nextInt();
            int[] g = new int[n];
            for(int i=0;i<n;i++) {
                g[i] = sc.nextInt();
            }
            Task task = new Task(n,p,g);
            solver.addTask(task);
        }
        solver.finish();
    }

 }
 class Task implements Callable<Object> {
    int n;
    int p;
    int[] g;


    public Task(int n, int p, int[] g) {
        super();
        this.n = n;
        this.p = p;
        this.g = g;
    }


    @Override
    public Object call() throws Exception {
        Arrays.fill(dp, (byte) -1);
        pow[0] = 1;
        for(int i=1;i<p;i++) {
            pow[i] = pow[i-1] * BASE;
        }
        int sum = 0;
        int[] count = new int[p];
        for(int i=0;i<n;i++) {
            count[g[i] % p]++;
            sum += g[i];
        }
        summod = sum % p;
        int x0 = 0;
        for(int i=0;i<p;i++) {
            x0 += pow[i] * count[i];
        }
        return f(x0);
    }

    int summod;
    private static final int BASE = 101;
    byte[] dp = new byte[110000000];
    int[] pow = new int[4];
    public byte f(int x) {
        if (x == 0) {
            return 0;
        }
        if (dp[x] >= 0) {
            return dp[x];
        }
        int y = x;
        int[] temp = new int[p];
        for(int i=0;i<p;i++) {
            temp[i] = y % BASE;
            y /= BASE;
        }
        int sum = 0;
        for(int i=0;i<p;i++) {
            sum += temp[i] * i;
        }

        int max = -1;
        for(int i=0;i<p;i++) {
            if (temp[i] <= 0) continue;
            max = Math.max(max, f(x - pow[i]) + (sum % p == summod ? 1 : 0));
        }
        return dp[x] = (byte) max;
    }

 }

