        out.write(ans.toString());
        out.flush();
        out.close();

    }

    private int solve()
    {

        int min =Integer.MAX_VALUE;
        for (int mask = 0; mask < (1 << (R * C)); mask++)
        {

            g = new boolean[R][C];
            int count = 0;
            for (int i = 0; i < R * C; i++)
            {
                int r = i / C;
                int c = i % C;
                if (((mask & (1 << i)) == 0))
                    g[r][c] = false;
                else
                {
                    g[r][c] = true;
                    count++;
                }
            }
            if (count != n)
                continue;


            int unhap = countUnHappiness();
            min = Math.min(min, unhap);
        }

        return min;
    }

    private int countUnHappiness()
    {
        int count = 0;
        for (int r = 0; r < R; r++)
            for (int c = 0; c < C; c++)
                if (g[r][c])
                    for (int i = 0; i < 4; i++)
                    {
                        int r2 = r + dx[i];
                        int c2 = c + dy[i];
                        if (valid(r2, c2))
                            if (g[r2][c2])
                                count++;

                    }
        return count / 2;
    }

    private boolean valid(int r, int c)
    {
        return r >= 0 && r < R && c >= 0 && c < C;
    }

    private void printG()
    {
        for (int i = 0; i < R; i++)
        {
            for (int j = 0; j < C; j++)
                if (g[i][j])
                    System.out.print("1 ");
                else
                    System.out.print("0 ");
            System.out.println();
        }
        System.out.println();

    }

 }
