            int N=sc.nextInt();
            int[] P=new int[N];
            for (int i=0;i<N;i++){
                P[i]=sc.nextInt();
            }
            String ss=""+solve(N,P);
            System.out.println("Case #"+t+": "+ss);
            outputFile.println("Case #"+t+": "+ss);


        }



        sc.close();
        outputFile.close();


    }



    public static void main(String[] args) throws Exception {
        GCJ_templateA J=new GCJ_templateA();

        J.process();


