        sc.useLocale(Locale.US);

        int T=sc.nextInt();
        for (int t=1;t<=T;t++){

            R=sc.nextInt();
            C=sc.nextInt();
            W=sc.nextInt();
            String ss=solve();
            log(ss);

            System.out.println("Case #"+t+": "+ss);
            outputFile.println("Case #"+t+": "+ss);


        }




        outputFile.close();


    }



    public static void main(String[] args) throws Exception {
        GCJ_Battleship_v2 J=new GCJ_Battleship_v2();

        J.process();


