                                     K--;
                                 } else {
                                     pairJP[j][p]++;
                                 }
                                 if (pairJS[j][s] > 0) {
                                     K--;
                                 } else {
                                     pairJS[j][s]++;
                                 }
                                 if (pairPS[p][s] > 0) {
                                     K--;
                                 } else {
                                     pairPS[p][s]++;
                                 }

                                 used[j][p][s] = true;

                                 sb.append("\n");
                                 sb.append(1 + j);
                                 sb.append(" ");
                                 sb.append(1 + p);
                                 sb.append(" ");
                                 sb.append(1 + s);
                             }
                         }
                     }
                 }
             }

             return count + sb.toString();
         }
     }
