public class B_Qual_GCJ2015 {

     public static long MOD = 1000000007;
     static int[] X = {0, 1};
     static int[] Y = {1, 0};
     static int[][][] dp;
     static boolean print = false;

     public static void main(String[] args) throws FileNotFoundException {
         PrintWriter out = new PrintWriter(new FileOutputStream(new File("output.txt")));

         Scanner in = new Scanner();
         int T = in.nextInt();
         for (int t = 0; t < T; t++) {
             int result = 0;
             int max = 0;
             int D = in.nextInt();
             ArrayList<Integer> list = new ArrayList();






             for (int i = 0; i < D; i++) {
                 int v = in.nextInt();
                 max = Math.max(v, max);

                 list.add(v);
             }












             Collections.sort(list);

             int x = cal(1, max, list);




             out.println("Case #" + (t + 1) + ": " + x);
         }
         out.close();
     }

     public static int cal(int minute, int max, ArrayList<Integer> list) {
         if (minute >= max) {
             return max;
         }

         ArrayList<Integer> tmp = new ArrayList();
         for (int i : list) {
             if (i > 1) {
                 tmp.add(i - 1);
             }
         }
         if (tmp.isEmpty()) {
             return minute;
         }

         int result = cal(minute + 1, max, tmp);
         int last = list.get(list.size() - 1);
         for (int i = 1; i <= last / 2; i++) {
             int a = i;
             int b = last - a;
             tmp = new ArrayList();
             tmp.addAll(list);
             tmp.remove((int) tmp.size() - 1);
             tmp.add(a);
             tmp.add(b);
             Collections.sort(tmp);
             result = Math.min(result, cal(minute + 1, max, tmp));
         }

         return result;
     }

     public static int[] KMP(String val) {
         int i = 0;
         int j = -1;
         int[] result = new int[val.length() + 1];
         result[0] = -1;
         while (i < val.length()) {
             while (j >= 0 && val.charAt(j) != val.charAt(i)) {
                 j = result[j];
             }
             j++;
             i++;
             result[i] = j;
         }
         return result;

     }

     public static boolean nextPer(int[] data) {
         int i = data.length - 1;
         while (i > 0 && data[i] < data[i - 1]) {
             i--;
         }
         if (i == 0) {
             return false;
         }
         int j = data.length - 1;
         while (data[j] < data[i - 1]) {
             j--;
         }
         int temp = data[i - 1];
         data[i - 1] = data[j];
         data[j] = temp;
         Arrays.sort(data, i, data.length);
         return true;
     }

     public static int digit(long n) {
         int result = 0;
         while (n > 0) {
             n /= 10;
             result++;
         }
         return result;
     }

     public static double dist(long a, long b, long x, long y) {
         double val = (b - a) * (b - a) + (x - y) * (x - y);
         val = Math.sqrt(val);
         double other = x * x + a * a;
         other = Math.sqrt(other);
         return val + other;



     }

     public static class Point implements Comparable<Point> {

         int x, y;

         public Point(int start, int end) {
             this.x = start;
             this.y = end;
         }

         @Override
         public int hashCode() {
             int hash = 5;
             hash = 47 * hash + this.x;
             hash = 47 * hash + this.y;
             return hash;
         }

         @Override
         public boolean equals(Object obj) {
             if (obj == null) {
                 return false;
             }
             if (getClass() != obj.getClass()) {
                 return false;
             }
             final Point other = (Point) obj;
             if (this.x != other.x) {
                 return false;
             }
             if (this.y != other.y) {
                 return false;
             }
             return true;
         }

         @Override
         public int compareTo(Point o) {
             return x - o.x;
         }
     }

     public static class FT {

         long[] data;

         FT(int n) {
             data = new long[n];
         }

         public void update(int index, long value) {
             while (index < data.length) {
                 data[index] += value;
                 index += (index & (-index));
             }
         }

         public long get(int index) {
             long result = 0;
             while (index > 0) {
                 result += data[index];
                 index -= (index & (-index));
             }
             return result;

         }
     }

     public static long gcd(long a, long b) {
         if (b == 0) {
             return a;
         }
         return gcd(b, a % b);
     }

     public static long pow(long a, long b) {
         if (b == 0) {
             return 1;
         }
         if (b == 1) {
             return a;
         }
         long val = pow(a, b / 2);
         if (b % 2 == 0) {
             return val * val % MOD;
         } else {
             return val * (val * a % MOD) % MOD;


         }
     }

     static class Scanner {

         BufferedReader br;
         StringTokenizer st;

         public Scanner() throws FileNotFoundException {


              br = new BufferedReader(new InputStreamReader(new FileInputStream(new File("B-small-attempt4.in"))));
         }

         public String next() {

             while (st == null || !st.hasMoreTokens()) {
                 try {
                     st = new StringTokenizer(br.readLine());
                 } catch (Exception e) {
                     throw new RuntimeException();
                 }
             }
             return st.nextToken();
         }

         public long nextLong() {
             return Long.parseLong(next());
         }

         public int nextInt() {
             return Integer.parseInt(next());
         }

         public double nextDouble() {
             return Double.parseDouble(next());
         }

         public String nextLine() {
             st = null;
             try {
                 return br.readLine();
             } catch (Exception e) {
                 throw new RuntimeException();
             }
         }

         public boolean endLine() {
             try {
                 String next = br.readLine();
                 while (next != null && next.trim().isEmpty()) {
                     next = br.readLine();
                 }
                 if (next == null) {
                     return true;
                 }
                 st = new StringTokenizer(next);
                 return st.hasMoreTokens();
             } catch (Exception e) {
                 throw new RuntimeException();
             }
         }
     }
