                cur += k++;
                if ( ++c >= C) {
                    ans.add(cur);
                    c = 0;
                    cur = 0;
                } else {
                    cur *= K;
                }
            }
            if ( cur != 0 ) {
                ans.add(cur);
            }
            if ( ans.size() == 0 ) {
                ans.add(0L);
            }
            if ( ans.size() <= S ) {
                bw.write("Case #" + (i + 1) + ":");
                for (long a:ans) {
                    bw.write(" " + (a + 1));
                }
            } else {
                bw.write("Case #" + (i + 1) + ": " + "IMPOSSIBLE");
            }

            bw.write("\r\n");
        }
        bw.close();
        br.close();
    }
