 public class AbtRicReader {

    public enum Type{
        INTEGER, STRING;
    }

    FileReader reader;
    public String[] buffer;
    boolean done = false;

    public AbtRicReader() {

    }

    public AbtRicReader(String file) {
        try {
            reader = new FileReader(file);
            int tmp = reader.read();
            String current = "";
            ArrayList<String> bufferlist = new ArrayList<String>();
            while (true) {
                if(tmp == 10) {
                    bufferlist.add(current);
                    break;
                } else if(tmp == 32) {
                    bufferlist.add(current);
                    current = "";
                    tmp = reader.read();
