         nx = new int[m];
         dst = new int[m];
         src = new int[m];
         cp = new int[m];
         fl = new int[m];
         Arrays.fill(head, -1);
         z = new boolean[n];
     }

     void addEdge(int x, int y, int capacity) {
         if (last == nx.length) {
             int size = nx.length * 2;
             nx = setSize(nx, size);
             dst = setSize(dst, size);
             src = setSize(src, size);
             cp = setSize(cp, size);
             fl = setSize(fl, size);
         }
         nx[last] = head[x];
         src[last] = x;
         dst[last] = y;
         cp[last] = capacity;
         head[x] = last;
         last++;
         nx[last] = head[y];
         src[last] = y;
         dst[last] = x;
         cp[last] = 0;
         head[y] = last;
         last++;
     }

     private int[] setSize(int[] x, int size) {
         int[] xx = new int[size];
         System.arraycopy(x, 0, xx, 0, x.length);
         return xx;
     }

     long maxFlow(int s, int t) {
         long res = 0;
         while (true) {
             Arrays.fill(z, false);
             int f = dfs(s, t, Integer.MAX_VALUE);
             if (f > 0) {
                 res += f;
             } else {
                 break;
             }
         }
         return res;
     }

     private int dfs(int x, int t, int f) {
         if (f == 0) return 0;
