             int y = dst[j];
             if (!z[y] && fl[j] < cp[j]) {
                 int res = dfs(y, t, Math.min(f, cp[j] - fl[j]));
                 if (res > 0) {
                     fl[j] += res;
                     fl[j ^ 1] -= res;
                     return res;
                 }
             }
             j = nx[j];
         }
         return 0;
     }

