public class B {
    FastScanner in = new FastScanner(System.in);
    PrintWriter out = new PrintWriter(System.out);

    long two(int x) {
        long res = 1;
        while (x > 0) {
            res *= 2;
            x--;
        }
        return res;
    }

    public void run() {
        int T = in.nextInt();
        for (int caseN = 1; caseN <= T; caseN++) {
            int B = in.nextInt();
            long M = in.nextLong();
            if (two(B-2) < M) {
                out.println("Case #" + caseN + ": IMPOSSIBLE");
                continue;
            }           

            int[][] res = new int[B][B];
            for (int i = 0; i < B - 1; i++) {
                for (int j = i + 1; j < B - 1; j++) {
                    res[i][j] = 1;
                }
            }

            long rest = M;
            for (int from = B - 2; from >= 0; from--) {
                long val = (from == 0) ? 1 : two(from-1);
                if (rest >= val) {
                    rest -= val;
                    res[from][B-1] = 1;
                }
            }
            out.println("Case #" + caseN + ": POSSIBLE");
            for (int i = 0; i < B; i++) {
                for (int j = 0; j < B; j++) {
                    out.print(res[i][j]);
                }
                out.println();
            }
        }
        out.close();
    }

