            for (int i = 0; i < n; i++) {
                r[i] = a[i].r;
                c[i] = a[i].c;
            }
            double sumC = 0, sumR = 0;
            for (int i = 0; i < n; i++) {
                sumC += c[i] * r[i];
                sumR += r[i];
