     static class TaskB {
         public void solve(int testNumber, InputReader in, PrintWriter out) {
             out.print("Case #" + testNumber + ": ");
             int N = in.nextInt();
             int C = in.nextInt();
             int M = in.nextInt();
             int[][] tickets = new int[C][N];
             for (int i = 0; i < M; i += 1) {
                 int p = in.nextInt() - 1;
                 int c = in.nextInt() - 1;
                 tickets[c][p] += 1;
             }
             int acount = 0;
             int bcount = 0;
             for (int i = 0; i < N; i += 1) {
                 acount += tickets[0][i];
                 bcount += tickets[1][i];
             }
             int ans = Math.max(acount, bcount);
             tickets[0][0] -= Math.min(tickets[0][0], bcount - tickets[1][0]);
             tickets[1][0] -= Math.min(tickets[1][0], acount - tickets[0][0]);
             int firstconflict = Math.min(tickets[0][0], tickets[1][0]);
             ans += firstconflict;
             int promo = 0;
             for (int i = 1; i < N; i += 1) {
                 int sum = tickets[0][i] + tickets[1][i];
                 if (sum > ans) {
                     promo += sum - ans;
                 }
             }
             out.print(ans);
             out.print(" ");
             out.println(promo);
         }

     }

     static class InputReader {
         public BufferedReader reader;
         public StringTokenizer tokenizer;

         public InputReader(InputStream stream) {
             reader = new BufferedReader(new InputStreamReader(stream));
             tokenizer = null;
         }

         public String next() {
             while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                 try {
                     tokenizer = new StringTokenizer(reader.readLine());
                 } catch (IOException e) {
                     throw new RuntimeException(e);
                 }
             }
             return tokenizer.nextToken();
         }

         public int nextInt() {
             return Integer.parseInt(next());
         }

     }
 }

