 class TaskA {
     public void solve(int testNumber, InputReader in, PrintWriter out) {
         out.print("Case #" + testNumber + ": ");
         int N = in.nextInt();
         if (N <= 10) {
             out.println(N);
             return;
         }
         int[] dp = new int[N+1];
         dp[1] = 1;
         boolean[] visit = new boolean[N+1];
         visit[1] = true;
         int[] v = new int[N];
         v[0] = 1;
         int p = 1;
         for (int i = 0; i < N; i++) {
             if (v[i] == N) {
                 out.println(dp[N]);
                 return;
             }
             if (!visit[v[i]+1]) {
                 visit[v[i]+1] = true;
                 dp[v[i]+1] = dp[v[i]] + 1;
                 v[p++] = v[i]+1;
             }
             int r = reverse(v[i]);
             if (r <= N && !visit[r]) {
                 visit[r] = true;
                 dp[r] = dp[v[i]] + 1;
                 v[p++] = r;
             }
         }
     }
     private int reverse(int N) {
         int res = 0;
         while (N > 0) {
             res *= 10;
             res += N%10;
             N /= 10;
         }
         return res;
     }
 }

