 class TaskC {
     public void solve(int testNumber, InputReader in, PrintWriter out) {
         out.print("Case #" + testNumber + ": ");
         int N = in.nextInt();
         int[] s = new int[500001];
         int[] m = new int[500001];
         int p = 0;
         for (int i = 0; i < N; i++) {
             int D = in.nextInt();
             int NUM = in.nextInt();
             int M = in.nextInt();
             for (int j = 0; j < NUM; j++) {
                 s[p] = D;
                 m[p] = M+j;
                 p++;
             }
         }
         int ans = p;
         for (int i = 0; i < p; i++) {
             double time = (360-s[i])/360.0 * m[i];
             int encounter = 0;
             for (int j = 0; j < p; j++) {
                 if (i == j) continue;
                 double rotate = time / m[j] * 360 + s[j];
                 if (rotate < 360) {
                     encounter++;
                 } else if (rotate >= 720) {
                     encounter += Math.floor(rotate/360);
                 }
             }
             ans = Math.min(ans, encounter);
         }
         out.println(ans);
     }
 }

