    {
        int n = s.length;
        int sc = 0;
        for(int q = n-1;q >= 0;q--){
            for(int i = 0;i < n-1;i++){
                if(s[i] == s[i+1]){
                    sc += 10;
                    for(int j = i;j < n-2;j++){
                        s[j] = s[j+2];
                    }
                    n -= 2;
                }
            }
        }
        sc += n/2*5;
        out.println(sc);
