import static java.lang.System.arraycopy;

 public class ProblemA1 {
     BufferedReader rd;

     ProblemA1() throws IOException {
         rd = new BufferedReader(new InputStreamReader(System.in));
         compute();
     }

     private void compute() throws IOException {
         int n = pint();
         for(int i=0;i<n;i++) {
             out("Case #" + (i + 1) + ":");
             solve();
         }
     }

     private void solve() throws IOException {
         int[] a = intarr();
         int r = a[0];
         int c = a[1];
         char[][] d = new char[r][];
         for(int i=0;i<r;i++) {
             d[i] = rd.readLine().trim().toCharArray();
         }
         for(int i=0;i<r;i++) {
             char last = 0;
             for(int j=0;j<c;j++) {
                 if(d[i][j] != '?') {
                     last = d[i][j];
                     int k = j-1;
                     while(k >= 0) {
                         if(d[i][k] == '?') {
                             d[i][k] = last;
                         } else {
                             break;
                         }
                         k--;
                     }
                 }
             }
             if(last != 0) {
                 int k = c-1;
                 while(k >= 0) {
                     if(d[i][k] == '?') {
                         d[i][k] = last;
                     } else {
                         break;
                     }
                     k--;
                 }
             }
         }
         boolean changed = true;
         while(changed) {
             changed = false;
             for(int i=0;i<r;i++) {
                 if(d[i][0] == '?') {
                     int ref = -1;
                     if(i > 0) {
                         if(d[i-1][0] != '?') {
                             ref = i-1;
                         }
                     }
                     if(ref == -1) {
                         if (i < r - 1) {
                             if (d[i + 1][0] != '?') {
                                 ref = i + 1;
                             }
                         }
                     }
                     if(ref != -1) {
                         arraycopy(d[ref],0,d[i],0,c);
                         changed = true;
                     }
                 }
             }
         }
         for(int i=0;i<r;i++) {
             out(new String(d[i]));
         }
     }

     private int[] intarr() throws IOException {
         return intarr(rd.readLine());
     }

     private int[] intarr(String s) {
         String[] q = split(s);
         int n = q.length;
         int[] a = new int[n];
         for(int i=0;i<n;i++) {
             a[i] = Integer.parseInt(q[i]);
         }
         return a;
     }

