package r1a;







 import static java.util.Arrays.*;

 public class C {

    static
    class Config {
        public static final boolean DISP_PROGRESS = true;
        public static final boolean DISP_ELASPED_TIME = true;
        public static final boolean STDIO = false;

        public static final String BASE_DIR = "data\\r1a" ;
        public static final String IN_FILE = "C-small-attempt1.in";
        public static final String OUT_FILE = IN_FILE + "_out.txt";
        public static final int MAX_THREAD = 3;
    }


    static
    class ParallelSolver implements Runnable {
        private static final int mod = (int)1e9+7;

        long hd, ad, hk, ak, b, d;
        public void readInput(final IOFast io) throws IOException {
            hd = io.nextLong();
            ad = io.nextLong();
            hk = io.nextLong();
            ak = io.nextLong();
            b = io.nextLong();
            d = io.nextLong();
        }

        @Override
        public void run() {
            long ans = Long.MAX_VALUE;
            for (int i = 0; i <= 100; i++) {
                ans = Math.min(ans, func(i));
            }
            out(ans);
        }

        long func(long debuff) {
            long hp = this.hd;
            long ak = this.ak;
            long turn = 0;
            boolean healed = false;
            for (int i = 0; i < debuff; turn++) {
                if (hp <= ak - d) { if (healed) return Long.MAX_VALUE; healed = true; hp = hd; hp -= ak; }
                else { healed = false; ak -= d; hp -= ak; i++; }
            }
            long ans = Long.MAX_VALUE;
            for (int i = 0; i <= 100; i++) {
                ans = Math.min(ans, func2(turn, hp, ak, i));
            }
            return ans;
        }

        long func2(long turn, long hp, long ak, long buff) {
            long ad = this.ad;
            boolean healed = false;
            for (int i = 0; i < buff; turn++) {
                if (hp <= ak) { if (healed) return Long.MAX_VALUE; healed = true; hp = hd; hp -= ak; }
                else { healed = false; ad += b; hp -= ak; i++; }
            }


            long hk = this.hk;
            for (; hk > 0; turn++) {
                if (hk <= ad) { hk -= ad; }
                else if (hp <= ak) { if (healed) return Long.MAX_VALUE; healed = true; hp = hd; hp -= ak; }
                else { healed = false; hk -= ad; hp -= ak; }
            }

            return turn;
        }

        void out(long ans) {
            if (ans == Long.MAX_VALUE) out.println("IMPOSSIBLE");
            else out.println(ans);
        }


        void printList(int[] res) {
            for(int i = 0; i < res.length; i++) {
                out.print(res[i] + (i==res.length-1?"\n":" "));
            }
        }
        void printList(List<Integer> res) {
            for(int i = 0; i < res.size(); i++) {
                out.print(res.get(i) + (i==res.size()-1?"\n":" "));
            }
        }


        final Random random = new Random(System.currentTimeMillis());
        final StringWriter sw = new StringWriter();
        final PrintWriter out = new PrintWriter(sw);

        @Override
        public String toString() {
            out.flush();
            return sw.toString();
        }

        public ParallelSolver init(final IOFast io) throws IOException {
            readInput(io);
            return this;
        }
    }

