    class ParallelSolver implements Runnable {
        private static final int mod = (int)1e9+7;

        int kind;
        int n;
        int[][] cs;
        public void readInput(final IOFast io) throws IOException {
            n = io.nextInt();
            cs = new int[n][2];
            TreeMap<String, Integer> mp = new TreeMap<>();
            for(int i = 0; i < n; i++) {
                for(int j = 0; j < 2; j++) {
                    String s = io.nextString();
                    if(!mp.containsKey(s)) mp.put(s, mp.size());
                    cs[i][j] = mp.get(s);
                }
            }
            kind = mp.size();
        }

        @Override
        public void run() {
            out.println(slow(cs));
        }

        int slow(int[][] cs) {
            TreeSet<Integer> set = new TreeSet<>();
            int[] comp = new int[cs.length];
            for(int i = 0; i < comp.length; i++) {
                comp[i] = cs[i][0] << 16 | cs[i][1];
                set.add(cs[i][0]);
            }
            Arrays.sort(comp);
            val = new int[set.size()][];
            for(int i = 0, j, idx = 0; i < comp.length; i = j) {
                for(j = i + 1; j < comp.length; j++) {
                    if((comp[i]>>16) != (comp[j]>>16)) {
                        break;
                    }
                }
                val[idx] = new int[j - i];
                for(int k = 0; k < j - i; k++) {
                    val[idx][k] = comp[i + k] & 0xFFFF;
                }
                idx++;
            }
            ap = new boolean[kind];
            vis = new int[set.size()];
            return dfs(0);
        }

        int[][] val;
        int[] vis;
        boolean[] ap;
        int dfs(int idx) {
            int ret = 0;
            if(idx >= val.length) {
                Arrays.fill(ap, false);
                for(int x : vis) ap[x] = true;
                for(int i = 0; i < val.length; i++) {
                    for(int x : val[i]) {
                        if(x != -1) {
                            if(ap[x]) ret++;
                            ap[x] = true;
                        }
                    }
                }
                return ret;
            }

            for(int i = 0; i < val[idx].length; i++) {
                int t = val[idx][i];
                vis[idx] = t;
                val[idx][i] = -1;
                ret = Math.max(ret, dfs(idx + 1));
                val[idx][i] = t;
            }
            return ret;
        }

        int tooslow(int[][] cs) {
            int[] comp = new int[cs.length];
            for(int i = 0; i < comp.length; i++) {
                comp[i] = cs[i][0] << 16 | cs[i][1];
            }
            Arrays.sort(comp);
            int ans = 0;
            int[] ap = new int[kind];
            do {
                Arrays.fill(ap, 0);
                int cnt = 0;
                for(int i = 0; i < comp.length; i++) {
                    int flag = 0;
                    if((ap[comp[i] >> 16] & 2) != 0) {
                        flag |= 2;
                    }
                    if((ap[comp[i] & 0xFFFF] & 1) != 0) {
                        flag |= 1;
                    }
                    if(flag == 3) cnt++;
                    ap[comp[i] >> 16] |= 2;
                    ap[comp[i] & 0xFFFF] |= 1;
                }
                ans = Math.max(ans, cnt);
            } while(nextPermutation(comp));
            return ans;
        }

        private static final void swap(int[] xs, int i, int j) {
            final int t = xs[j];
            xs[j] = xs[i];
            xs[i] = t;
        }
        private static final boolean nextPermutation(final int[] xs) {
            for(int i = xs.length - 1; i > 0; i--) {
                if(xs[i - 1] > xs[i]) {
                    continue;
                }

                for(int j = i, k = xs.length - 1; j < k; j++, k--) {
                    swap(xs, j, k);
                }

                for(int j = i; j < xs.length; j++) if(xs[j] > xs[i - 1]) {
                    swap(xs, j, i - 1);
                    break;
                }

                return true;
            }
            return false;
        }



