import static java.lang.Integer.parseInt;
 import static java.lang.Long.parseLong;
 import static java.lang.Math.max;
 import static java.lang.System.arraycopy;
 import static java.lang.System.exit;
 import static java.util.Arrays.copyOf;
 import static java.util.Arrays.fill;








 public class A {

    static class IntList {

        int data[] = new int[3];
        int size = 0;

        boolean isEmpty() {
            return size == 0;
        }

        int size() {
            return size;
        }

        int get(int index) {
            if (index < 0 || index >= size) {
                throw new IndexOutOfBoundsException();
            }
            return data[index];
        }

        void clear() {
            size = 0;
        }

        void set(int index, int value) {
            if (index < 0 || index >= size) {
                throw new IndexOutOfBoundsException();
            }
            data[index] = value;
        }

        void expand() {
            if (size >= data.length) {
                data = copyOf(data, (data.length << 1) + 1);
            }
        }

        void insert(int index, int value) {
            if (index < 0 || index > size) {
                throw new IndexOutOfBoundsException();
            }
            expand();
            arraycopy(data, index, data, index + 1, size++ - index);
            data[index] = value;
        }

        int delete(int index) {
            if (index < 0 || index >= size) {
                throw new IndexOutOfBoundsException();
            }
            int value = data[index];
            arraycopy(data, index + 1, data, index, --size - index);
            return value;
        }

        void push(int value) {
            expand();
            data[size++] = value;
        }

        int pop() {
            if (size == 0) {
                throw new NoSuchElementException();
            }
            return data[--size];
        }

        void unshift(int value) {
            expand();
            arraycopy(data, 0, data, 1, size++);
            data[0] = value;
        }

        int shift() {
            if (size == 0) {
                throw new NoSuchElementException();
            }
            int value = data[0];
            arraycopy(data, 1, data, 0, --size);
            return value;
        }
    }

    static final int LIM = 1000000;

    static void solve() throws Exception {
        IntList edges[] = new IntList[LIM];
        int n = scanInt();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 6; j++) {
                int v = scanInt() - 1;
                if (edges[v] == null) {
                    edges[v] = new IntList();
                }
                edges[v].push(i);
            }
        }
        int matchL[] = new int[LIM];
        int matchR[] = new int[n];
        fill(matchL, -1);
        fill(matchR, -1);
        int queue[] = new int[LIM];
        int back[] = new int[LIM];
        boolean used[] = new boolean[LIM];
        int ans = 0;
        int rangeStart = 0, rangeEnd = 0;
        for (int i = 0; i < LIM; i++) {
            if (edges[i] == null) {

                for (int j = rangeStart; j < rangeEnd; j++) {
                    matchR[matchL[j]] = -1;
                    matchL[j] = -1;
                }
                rangeStart = rangeEnd = i + 1;
                continue;
            }
            int queueHead = 0, queueTail = 1;
            queue[0] = i;
            used[i] = true;
            back[i] = -1;
            boolean found = false;
            bfs: do {
                int cur = queue[queueHead++];
                IntList cedges = edges[cur];
                for (int j = 0; j < cedges.size(); j++) {
                    int next = cedges.get(j);
                    if (matchR[next] < 0) {
                        matchR[next] = cur;
                        while (back[cur] >= 0) {
                            int prev = back[cur];
                            int pnext = matchL[cur];
                            matchL[cur] = next;
                            matchR[pnext] = prev;
                            cur = prev;
                            next = pnext;
                        }
                        matchL[cur] = next;
                        found = true;
                        break bfs;
                    } else if (!used[matchR[next]]) {
                        used[matchR[next]] = true;
                        queue[queueTail++] = matchR[next];
                        back[matchR[next]] = cur;
                    }
                }
            } while (queueHead != queueTail);


            if (!found) {

                while (true) {
                    if (rangeStart == rangeEnd) {
                        throw new AssertionError();
                    }
                    matchR[matchL[rangeStart]] = -1;
                    matchL[rangeStart] = -1;
