    static boolean seen3[]; 
    static boolean sink[];

    static String i2w(int i) {
        char res[] = new char[5];
        for (int j = 0; j < 5; j++) {
            res[j] = (char) ('a' + (i % 26));
            i /= 26;
        }
        return new String(res);
