        for (int id: sinkL) {
            sink[id] = true;
        }
        int flow = 0;
        for (int source: sourceL) {
            fill(seen1, false);
            fill(seen2, false);
            fill(seen3, false);
            if (dfs1(source)) {
                ++flow;
            }
        }
        printCase();
        out.println(flow);
