    static boolean dfs1(int cur) {
        if (seen1[cur]) {
            return false;
        }
        seen1[cur] = true;
        if (!iEdges[cur]) {
            iEdges[cur] = true;
            if (dfs3(cur)) {
                return true;
            }
            iEdges[cur] = false;
        }
        for (Edge e: rEdges2[cur]) {
            if (e.reverseCap > 0) {
                --e.reverseCap;
                if (dfs2(e.from)) {
                    return true;
                }
                ++e.reverseCap;
            }
        }
        return false;
    }

    static boolean dfs2(int cur) {
        if (seen2[cur]) {
            return false;
        }
        seen2[cur] = true;
        for (Edge e: rEdges1[cur]) {
            if (e.reverseCap > 0) {
                --e.reverseCap;
                if (dfs3(e.from)) {
                    return true;
                }
                ++e.reverseCap;
            }
        }
        for (Edge e: edges2[cur]) {
            ++e.reverseCap;
            if (dfs1(e.to)) {
                return true;
            }
            --e.reverseCap;
        }
        return false;
    }   

    static boolean dfs3(int cur) {
        if (seen3[cur]) {
            return false;
        }
        seen3[cur] = true;
        if (sink[cur]) {
            return true;
        }
        if (iEdges[cur]) {
            iEdges[cur] = false;
            if (dfs1(cur)) {
                return true;
            }
            iEdges[cur] = true;
        }
        for (Edge e: edges1[cur]) {
            ++e.reverseCap;
            if (dfs2(e.to)) {
                return true;
            }
            --e.reverseCap;
        }
        return false;
    }

