     static class TaskA {
         public void solve(int testNumber, InputReader in, OutputWriter out) {
             out.printFormat("Case #%d: ", testNumber);
             int n = in.readInt();
             int p = in.readInt();
             int[] a = IOUtils.readIntArray(in, n);
             int[] cnt = new int[p];
             int sum = 0;
             for (int x : a) {
                 sum += x;
                 cnt[x % p]++;
             }
             if (sum % p != 0) {
                 cnt[p - sum % p]++;
             }
             int ans = cnt[0];
             cnt[0] = 0;
             if (p == 2) {
                 ans += cnt[1] / 2;
             }
             if (p == 3) {
                 int mn = Math.min(cnt[1], cnt[2]);
                 ans += mn;
                 cnt[1] -= mn;
                 cnt[2] -= mn;
                 ans += cnt[1] / 3;
                 ans += cnt[2] / 3;
             }
             if (p == 4) {
                 int mn = Math.min(cnt[1], cnt[3]);
                 ans += mn;
                 cnt[1] -= mn;
                 cnt[3] -= mn;
                 ans += cnt[1] / 4;
                 ans += cnt[3] / 4;
                 ans += cnt[2] / 2;
             }
             out.printLine(ans);
         }

     }

