        if (spaceFlag) {
            System.out.print(" ");
        } else {
            spaceFlag=true;
        }
        System.out.print(set[i]);
        }
        System.out.println();
        boolean result1 = next_ksubset(n,set);
        if (!result1) {
        break;
        }
    }

     }


