     public static final int MOD = 9901;
     public static final int UNDEF = -3;



     private void run(int caseNumber) throws Exception {
         String S = STR();
         int K = INT();


         if(debugTestCases.length>0 && Arrays.binarySearch(debugTestCases, caseNumber)<0) {
             if(writeToFile) {
                 out.printf("Case #%d: skip\n", caseNumber);
             }
             return;
         }


         int res = INF;

         int beg = 0;
         for (int i = 0; i < S.length(); i++) {
             if (S.charAt(i)=='-') {
                 beg |= 1<<i;

             }

         }

         int bit = S.length()-K+1;
         int flip = (1<<K)-1;
         for (int msk = 0; msk < 1<<bit; msk++) {
             if (ok(beg,msk,bit,flip)) {
                 res = Math.min(res, bitCount(msk));

             }
         }
         out.printf("Case #%d: %s\n", caseNumber, res==INF?NO:res);


     }

     private boolean ok(int v, int msk, int bit, int flip) {
         for (int i = 0; i < bit; i++) {
             if (has(msk,i)) {
                 v ^= flip<<i;
             }
         }
         return v==0;
     }


     static int lowest(int mask) {
         return (mask & -mask);
     }


     static boolean has(int mask, int i) {
         return (mask & (1 << i)) != 0;
     }


     static int set(int mask, int i, boolean v) {
         return v ? set(mask, i) : unset(mask, i);
     }


     static int set(int mask, int i) {
         return mask | (1 << i);
     }


     static int unset(int mask, int i) {
         return mask & ~(1 << i);
     }


     static boolean contain(int set, int subset) {
         return (set & subset) == subset;
