             return (int) res;
         }

         public boolean equals(Object obj) {
             if (obj == null || getClass() != obj.getClass())
                 return false;
             XY other = (XY) obj;
             return beg == other.beg && end == other.end;
         }

         public int compareTo(XY other) {

             if (beg != other.beg)
