public class Main implements Runnable {

    final String problem = "B";


    final String filename = problem + "-small-attempt0";



    final double eps = 1e-7;

    public void solve() throws Exception {
        int N = iread();
        double V = (long) (dread() * 10000 + 0.5), X = (long) (dread() * 10000 + 0.5);
        Pair[] p = new Pair[N];
        for (int i = 0; i < N; i++)
            p[i] = new Pair((long) (dread() * 10000 + 0.5),
                    (long) (dread() * 10000 + 0.5));
        Arrays.sort(p);
        if (p[0].x > X || p[N - 1].x < X) {
            out.write("IMPOSSIBLE");
            return;
        }
        long S = 0, sum = 0;
        for (int i = 0; i < N; i++) {
            S += p[i].x * p[i].v;
            sum += p[i].v;
        }
        double ansV = sum;
        int left = 0, right = N - 1;
        if (X * sum < S) {
            while (X * sum < S) {
                S -= p[right].x * p[right].v;
                sum -= p[right].v;
                if (X * sum - S < 0) {
                    right--;
                } else {
                    double a = (X * sum - S) * 1.0 / (p[right].x - X);
                    ansV = sum + a;
                    break;
                }
            }
        } else
            while (X * sum > S) {
                S -= p[left].x * p[left].v;
                sum -= p[left].v;
                if (X * sum - S > 0) {
                    left++;
                } else {
                    double a = (X * sum - S) * 1.0 / (p[left].x - X);
                    ansV = sum + a;
                    break;
                }
            }
        out.write(df.format(V / ansV) + "");
    }

    DecimalFormat df = new DecimalFormat("0.000000000");

    class Pair implements Comparable<Pair> {
        public Pair(long v, long x) {
            super();
            this.x = x;
            this.v = v;
        }

        long x, v;

        @Override
        public int compareTo(Pair o) {
            return Long.compare(x, o.x);
        }
    }

