                 System.err.println("Generating " + dig);
                 result[dig] = new Counter<>();
                 int[] qty = new int[dig + 1];
                 int upTo = (int) IntegerUtils.power(10, dig);
                 for (int i = 1; i < upTo; i++) {
                     if (i % (upTo / 10) == 0) {
                         System.err.println("Done " + i);
                     }
                     boolean first = true;
                     int j = i;
                     long numWays = 1;
                     while (true) {
                         Arrays.fill(qty, 0);
