                 for (int x = 0; x < currentString.length(); x++) {
                     int digit = currentString.charAt(x) - '0';
                     if (!seenDigit[digit]) {
                         seenDigit[digit] = true;
                         seenCount++;
                     }
                 }
                 if (seenCount == 10) break;
                 currentNumber += input;
             }
             System.out.printf("Case #%d: %d%n", t, currentNumber);
         }
         sc.close();
     }
