public class C {
    int n;
    String[] s, t;

    String solve() {
        String[] ss = sortedUnique(s);
        String[] tt = sortedUnique(t);
        int a = ss.length;
        int b = tt.length;
        e = new boolean[a][b];
        for (int i = 0; i < n; i++) {
            int x = Arrays.binarySearch(ss, s[i]);
            int y = Arrays.binarySearch(tt, t[i]);
            e[x][y] = true;
        }
        int edgeCover = a + b - matching(); 
        return n - edgeCover + "";
    }

    public C(Scanner in) {
        n = in.nextInt();
        s = new String[n];
        t = new String[n];
        for (int i = 0; i < n; i++) {
            s[i] = in.next();
            t[i] = in.next();
        }
    }

    public boolean[][] e;

    private boolean[] mark;
    private int[] left;

    public int matching() {
        mark = new boolean[e.length];
        left = new int[e[0].length];
        Arrays.fill(left, -1);
        int ans = 0;
        for (int i = 0; i < e.length; i++) {
            Arrays.fill(mark, false);
            if (dfs(i)) {
                ans++;
            }
        }
        return ans;
    }

    private boolean dfs(int i) {
        if (mark[i]) {
            return false;
        }
        mark[i] = true;
        for (int j = 0; j < e[i].length; j++) {
            if (!e[i][j]) {
                continue;
            }
            if (left[j] == -1 || dfs(left[j])) {
                left[j] = i;
                return true;
            }
        }
        return false;
    }

    static String[] sortedUnique(String[] s) {
        TreeSet<String> treeSet = new TreeSet<String>(Arrays.asList(s));
        return treeSet.toArray(new String[treeSet.size()]);
    }

    public static void main(String[] args) throws Exception {
        int nThreads = 4;

        String fileNameSuffix = "";
        String formatOut = "Case #%2$d: %1$s";
        String formatSystemOut = formatOut;





