public class StandingOvation {

    FastScanner in;
    PrintWriter out;

    void solve() {
        int n = in.nextInt();
        String s = in.nextToken();
        int ans = 0, sum = 0;
        for (int i = 0; i < s.length(); i++) {
            int count = s.charAt(i) - '0';
            if (count == 0) {
                continue;
            }
            while (sum < i) {
                ans++;
                sum++;
            }
            sum += count;
